params.command:
$ErrorActionPreference='Stop'
$root = Join-Path $env:TEMP 'mhw-updater-e2e-artifacts-60-61'
if(Test-Path $root){Remove-Item -Recurse -Force $root}
New-Item -ItemType Directory -Path (Join-Path $root '60'),(Join-Path $root '61') | Out-Null
$expected60='EF9A9352C64C71C1D17947D17129F9CE2835BA14F63110047750CFFDDBB87F2B'
$expected61='C31CAA1F5CBA65EBF9D526B02BA718F807EBC18A7E7554269E3754D710F86420'
function Get-ReleaseAsset([string]$tag,[string]$dest){
  $gh=Get-Command gh -ErrorAction SilentlyContinue
  if($gh){
    & gh release download $tag --repo fengie/mhw-mods --pattern 'MHW-Manual-Mod-Manager-v8.8.4-win-x64.zip' --dir $dest --clobber
    if($LASTEXITCODE -eq 0){ return 'gh' }
  }
  $input = @"
protocol=https
host=github.com

"@
  $lines = $input | git credential fill
  if($LASTEXITCODE -ne 0){ throw "git credential fill failed for $tag" }
  $kv=@{}
  foreach($line in $lines){ if($line -match '^([^=]+)=(.*)$'){ $kv[$matches[1]]=$matches[2] } }
  if(-not $kv.ContainsKey('password') -or [string]::IsNullOrWhiteSpace($kv['password'])){ throw "no opaque GitHub credential available for $tag" }
  $headers=@{ Authorization="Bearer $($kv['password'])"; Accept='application/vnd.github+json'; 'X-GitHub-Api-Version'='2022-11-28' }
  $rel=Invoke-RestMethod -Headers $headers -Uri "https://api.github.com/repos/fengie/mhw-mods/releases/tags/$tag"
  $asset=$rel.assets | Where-Object name -eq 'MHW-Manual-Mod-Manager-v8.8.4-win-x64.zip' | Select-Object -First 1
  if(-not $asset){ throw "release asset missing for $tag" }
  $downloadHeaders=@{ Authorization="Bearer $($kv['password'])"; Accept='application/octet-stream'; 'X-GitHub-Api-Version'='2022-11-28' }
  Invoke-WebRequest -Headers $downloadHeaders -Uri $asset.url -OutFile (Join-Path $dest $asset.name)
  $kv.Clear()
  return 'git-credential-api'
}
$m60=Get-ReleaseAsset 'updater-main-60' (Join-Path $root '60')
$m61=Get-ReleaseAsset 'updater-main-61' (Join-Path $root '61')
$f60=Join-Path $root '60\MHW-Manual-Mod-Manager-v8.8.4-win-x64.zip'
$f61=Join-Path $root '61\MHW-Manual-Mod-Manager-v8.8.4-win-x64.zip'
$h60=(Get-FileHash $f60 -Algorithm SHA256).Hash
$h61=(Get-FileHash $f61 -Algorithm SHA256).Hash
if($h60 -ne $expected60){throw "build60 hash mismatch: $h60"}
if($h61 -ne $expected61){throw "build61 hash mismatch: $h61"}
Write-Output "ACQUIRE60=PASS METHOD=$m60 SHA256=$h60 PATH=$f60"
Write-Output "ACQUIRE61=PASS METHOD=$m61 SHA256=$h61 PATH=$f61"
Write-Output "ROOT=$root"
